public class Pizzabestellung {

    public static void bestellungDrucken(String geschmack, int stueck) {
        System.out.println("Bestellung: " + stueck + " x " + geschmack);
        double gesamt = stueck * 4.50;
        System.out.println("Summe: " + gesamt + " Euro");
    }

    public static void main(String[] args) {
        bestellungDrucken("Margherita", 2);
        bestellungDrucken("Salami", 1);
    }
}

